"""Route maths. The agent decides *what* should happen; this works out the order.

Given the vans that can still drive, where each one is and when it is free, and
the stops still to deliver, it returns a sequence per van. Lateness is allowed
but costs per minute, and it costs more for a pharmacy than for a house, so the
plan sacrifices the right deliveries when the day goes wrong.
"""
from ortools.constraint_solver import pywrapcp, routing_enums_pb2

LATE_COST_PER_MIN = {"pharmacy": 60, "clinic": 50, "restaurant": 25, "home": 4}
DROP_COST = 10_000_000  # only if a stop truly cannot fit


def plan(day, vans, todo, *, travel, now_min, extra_priority=(), earliest=None, seconds=3, max_stops=24):
    """
    vans:  [{"id", "at": node, "free_min": minute it can leave}]   (node 0 = depot)
    todo:  [order index (1-based node)]                            stops left
    travel(a, b) -> seconds between nodes, with any closures applied
    extra_priority: nodes the agent marked urgent (treated like a pharmacy)
    earliest: {node: minute} it cannot be delivered before (parcels in transit, customer asked)
    Returns {van_id: [node, ...]} and a list of dropped nodes.
    """
    if not vans or not todo:
        return {v["id"]: [] for v in vans}, list(todo)
    nodes = [0] + sorted(set(todo)) + sorted({v["at"] for v in vans} - {0} - set(todo))
    pos = {n: i for i, n in enumerate(nodes)}
    starts = [pos[v["at"]] for v in vans]
    ends = [0] * len(vans)
    mgr = pywrapcp.RoutingIndexManager(len(nodes), len(vans), starts, ends)
    rt = pywrapcp.RoutingModel(mgr)
    orders = day["orders"]

    def svc(n):
        return 0 if n == 0 else orders[n - 1]["service_min"]

    def cb(i, j):
        a, b = nodes[mgr.IndexToNode(i)], nodes[mgr.IndexToNode(j)]
        return round(travel(a, b) / 60) + svc(a)

    t = rt.RegisterTransitCallback(cb)
    rt.SetArcCostEvaluatorOfAllVehicles(t)
    horizon = 24 * 60
    rt.AddDimension(t, 120, horizon, False, "time")
    # A driver can only carry so much: cap the stops per van.
    one = rt.RegisterUnaryTransitCallback(lambda i: 0 if nodes[mgr.IndexToNode(i)] == 0 else 1)
    rt.AddDimensionWithVehicleCapacity(one, 0, [max_stops] * len(vans), True, "stops")
    dim = rt.GetDimensionOrDie("time")
    # Spread the work: a van finishing at 4 pm while another idles is a bad plan.
    dim.SetGlobalSpanCostCoefficient(40)
    for k, v in enumerate(vans):
        dim.CumulVar(rt.Start(k)).SetRange(max(int(v["free_min"]), now_min), horizon)
    for n in todo:
        idx = mgr.NodeToIndex(pos[n])
        o = orders[n - 1]
        kind = "pharmacy" if n in extra_priority else o["kind"]
        dim.SetCumulVarSoftUpperBound(idx, int(o["promise_min"]), LATE_COST_PER_MIN[kind])
        if earliest and n in earliest:
            dim.CumulVar(idx).SetMin(int(earliest[n]))
        rt.AddDisjunction([idx], DROP_COST)

    p = pywrapcp.DefaultRoutingSearchParameters()
    p.first_solution_strategy = routing_enums_pb2.FirstSolutionStrategy.PARALLEL_CHEAPEST_INSERTION
    p.local_search_metaheuristic = routing_enums_pb2.LocalSearchMetaheuristic.GUIDED_LOCAL_SEARCH
    p.time_limit.seconds = seconds
    sol = rt.SolveWithParameters(p)
    if not sol:
        return {v["id"]: [] for v in vans}, list(todo)

    out, seen = {}, set()
    for k, v in enumerate(vans):
        i, seq = rt.Start(k), []
        while not rt.IsEnd(i):
            n = nodes[mgr.IndexToNode(i)]
            if n in todo:
                seq.append(n)
                seen.add(n)
            i = sol.Value(rt.NextVar(i))
        out[v["id"]] = seq
    return out, [n for n in todo if n not in seen]
"""Detour's dispatcher: reads what people send, decides, re-plans, tells drivers, checks.

The model never moves a van or a dollar directly. It calls tools; the tools act on
the world and say what happened. Every call is traced in neatlogs.
"""
import json, os
from openai import OpenAI
import neatlogs
from neatlogs.decorators import span

from .solver import plan
from .world import hhmm
from . import payments

AUTO_REFUND_LIMIT = 10.00   # above this, a person approves
GOODWILL = 25.00            # credit for a business whose delivery was badly late

SYSTEM = """You are Detour, the dispatcher for a same-morning delivery fleet out of the Amazon DLA7 depot in Chino, California.
Messages arrive from drivers, customers, the warehouse and the city. For each one, work out what really changed and act with your tools.

Rules:
- Read the inbox, then fix things. A message only counts as handled once you have acted on it and called mark_handled.
- If something changes what the vans should do (a van out of action, a closed road, an urgent order, a customer asking for a later time), call replan once you have recorded the change, and check the forecast it returns.
- Tell every driver whose route changed, in one short plain message.
- Urgent medical deliveries come first: use set_priority with the deadline you were given.
- A customer who asks for a later time gets it: use set_customer_window. That is not a late delivery.
- Never invent an order id, van id or time. Use get_fleet to look things up.
- Be brief. You are on the clock."""

TOOLS = [
    {"name": "get_fleet", "description": "Every van: status, where it is going next, its remaining stops, and the forecast of late deliveries.", "parameters": {"type": "object", "properties": {}}},
    {"name": "read_inbox", "description": "Unhandled messages from drivers, customers, the warehouse and the city.", "parameters": {"type": "object", "properties": {}}},
    {"name": "mark_handled", "description": "Mark a message handled once you have acted on it.", "parameters": {"type": "object", "properties": {"message_id": {"type": "string"}, "summary": {"type": "string", "description": "one line: what you did"}}, "required": ["message_id", "summary"]}},
    {"name": "set_priority", "description": "Make an order urgent with a new deadline (HH:MM).", "parameters": {"type": "object", "properties": {"order_id": {"type": "string"}, "deadline": {"type": "string"}}, "required": ["order_id", "deadline"]}},
    {"name": "set_customer_window", "description": "The customer asked not to be delivered before this time (HH:MM).", "parameters": {"type": "object", "properties": {"order_id": {"type": "string"}, "not_before": {"type": "string"}}, "required": ["order_id", "not_before"]}},
    {"name": "retry_later", "description": "A delivery could not be made (locked gate, no answer). Try again no earlier than this many minutes from now.", "parameters": {"type": "object", "properties": {"order_id": {"type": "string"}, "minutes": {"type": "integer"}}, "required": ["order_id", "minutes"]}},
    {"name": "replan", "description": "Re-plan every remaining stop across the vans that can still drive, avoiding closed roads and respecting priorities and customer windows. Returns the forecast.", "parameters": {"type": "object", "properties": {}}},
    {"name": "message_driver", "description": "Send a short message to a driver.", "parameters": {"type": "object", "properties": {"van_id": {"type": "string"}, "text": {"type": "string"}}, "required": ["van_id", "text"]}},
]


def _parse_hhmm(s):
    h, m = str(s).strip().split(":")[:2]
    return int(h) * 60 + int(m)


class Dispatcher:
    def __init__(self, world, *, model=None, base_url=None, api_key=None, version="v1"):
        self.w = world
        self.version = version
        self.client = OpenAI(base_url=base_url or os.environ.get("LLM_BASE_URL"), api_key=api_key or os.environ.get("LLM_API_KEY"))
        self.model = model or os.environ.get("LLM_MODEL", "openai/gpt-oss-120b")
        self.forecast = None

    # ---------- tools ----------
    def _order_node(self, oid):
        for i, o in enumerate(self.w.orders):
            if o["id"] == oid:
                return i + 1
        raise ValueError(f"no order {oid}")

    @span(kind="TOOL", tool_name="get_fleet")
    def get_fleet(self):
        w = self.w
        vans = []
        for v in w.vans.values():
            nxt = w.orders[v["next"] - 1]["id"] if v["next"] else None
            vans.append({"van": v["id"], "status": v["status"], "next_stop": nxt,
                         "remaining": [w.orders[n - 1]["id"] for n in v["plan"]], "delivered": len(v["done"])})
        return {"clock": hhmm(w.clock), "vans": vans, "forecast": self.forecast}

    @span(kind="TOOL", tool_name="read_inbox")
    def read_inbox(self):
        return [m for m in self.w.inbox if not m["handled"]]

    @span(kind="TOOL", tool_name="mark_handled")
    def mark_handled(self, message_id, summary):
        for m in self.w.inbox:
            if m["id"] == message_id:
                m["handled"], m["summary"] = True, summary
                self.w.events.append({"t": self.w.clock, "kind": "handled", "message": message_id, "text": summary})
                return {"ok": True}
        return {"ok": False, "error": f"no message {message_id}"}

    @span(kind="TOOL", tool_name="set_priority")
    def set_priority(self, order_id, deadline):
        n = self._order_node(order_id)
        self.w.priority.add(n)
        self.w.orders[n - 1]["promise_min"] = min(self.w.orders[n - 1]["promise_min"], _parse_hhmm(deadline))
        return {"ok": True, "order": order_id, "deadline": deadline, "note": "call replan to act on it"}

    @span(kind="TOOL", tool_name="set_customer_window")
    def set_customer_window(self, order_id, not_before):
        n = self._order_node(order_id)
        self.w.earliest[n] = max(self.w.earliest.get(n, 0), _parse_hhmm(not_before))
        self.w.orders[n - 1]["customer_window"] = True
        return {"ok": True, "order": order_id, "not_before": not_before, "note": "call replan to act on it"}

    @span(kind="TOOL", tool_name="retry_later")
    def retry_later(self, order_id, minutes):
        n = self._order_node(order_id)
        # The van that was driving there skips it; the stop goes back into the pool.
        for v in self.w.vans.values():
            if v["next"] == n and v["status"] == "driving":
                v["next"], v["status"] = None, "idle"
                v["free_min"] = max(v["free_min"], v["arrive"])
                v["at"] = n
        self.w.earliest[n] = self.w.clock + int(minutes)
        return {"ok": True, "order": order_id, "retry_after": hhmm(self.w.clock + int(minutes)), "note": "call replan"}

    @span(kind="TOOL", tool_name="replan")
    def replan(self):
        w = self.w
        routes, dropped = plan(w.day, w.available_vans(), w.pending(), travel=w.travel, now_min=int(w.clock),
                               extra_priority=w.priority, earliest=w.earliest, seconds=3)
        before = {vid: list(v["plan"]) for vid, v in w.vans.items()}
        w.assign(routes)
        self.forecast = self._forecast()
        changed = [vid for vid in routes if routes[vid] != before.get(vid)]
        w.events.append({"t": w.clock, "kind": "replan", "changed": changed, "forecast": self.forecast})
        return {"changed_vans": changed, "dropped": [w.orders[n - 1]["id"] for n in dropped], "forecast": self.forecast}

    @span(kind="TOOL", tool_name="message_driver")
    def message_driver(self, van_id, text):
        if van_id not in self.w.vans:
            return {"ok": False, "error": f"no van {van_id}"}
        self.w.messages_out.append({"t": hhmm(self.w.clock), "van": van_id, "text": text})
        self.w.events.append({"t": self.w.clock, "kind": "to_driver", "van": van_id, "text": text})
        return {"ok": True}

    def _forecast(self):
        """Walk every plan forward on current road times and count who will be late."""
        w, late = self.w, []
        for v in w.available_vans():
            clock, at = v["free_min"], v["at"]
            for n in w.vans[v["id"]]["plan"]:
                clock = max(clock + w.travel(at, n) / 60, w.earliest.get(n, 0))
                o = w.orders[n - 1]
                promised = w.promised(n)
                if clock > promised:
                    late.append({"order": o["id"], "kind": o["kind"], "late_min": round(clock - promised)})
                clock += o["service_min"]
                at = n
        return {"late_count": len(late), "late": sorted(late, key=lambda x: -x["late_min"])[:8]}

    # ---------- the loop ----------
    def _call(self, name, args):
        fn = getattr(self, name, None)
        if not fn or name not in {t["name"] for t in TOOLS}:
            return {"error": f"unknown tool {name}"}
        try:
            return fn(**args)
        except Exception as e:
            return {"error": str(e)}

    @span(kind="AGENT", role="Dispatcher", goal="Keep every delivery on time through the chaos")
    def handle(self, new_messages, max_rounds=12):
        msgs = [{"role": "system", "content": SYSTEM},
                {"role": "user", "content": f"It is {hhmm(self.w.clock)}. New messages just arrived: "
                                            + json.dumps([{k: m[k] for k in ('id', 'from', 'text')} for m in new_messages])}]
        tools = [{"type": "function", "function": t} for t in TOOLS]
        for _ in range(max_rounds):
            r = self.client.chat.completions.create(model=self.model, messages=msgs, tools=tools, temperature=0.2)
            m = r.choices[0].message
            msgs.append({"role": "assistant", "content": m.content or "", "tool_calls": [tc.model_dump() for tc in (m.tool_calls or [])]} if m.tool_calls else {"role": "assistant", "content": m.content or ""})
            if not m.tool_calls:
                break
            for tc in m.tool_calls:
                try:
                    args = json.loads(tc.function.arguments or "{}")
                except json.JSONDecodeError:
                    args = {}
                out = self._call(tc.function.name, args)
                msgs.append({"role": "tool", "tool_call_id": tc.id, "content": json.dumps(out, default=str)[:6000]})
        return m.content

    @span(kind="CHAIN", name="close_out_late_deliveries")
    def close_out(self, approve=lambda req: True):
        """End of day: confirm each late delivery really was late, then refund it once."""
        w = self.w
        for n, t in sorted(w.delivered.items()):
            o = w.orders[n - 1]
            late = t - w.promised(n)
            if late <= 0 or n in w.refunds:
                continue
            amount = o["fee"] + (GOODWILL if o["kind"] != "home" and late > 30 else 0)
            req = {"order": o["id"], "kind": o["kind"], "late_min": round(late), "amount": round(amount, 2)}
            status = "auto"
            if amount > AUTO_REFUND_LIMIT:
                status = "approved" if approve(req) else "declined"
                if status == "declined":
                    w.refunds[n] = {"amount": 0, "status": "declined", **req}
                    continue
            w.refunds[n] = {**payments.refund(o, amount, reason=f"{round(late)} min late"), "status": status, **req}
        return w.refunds
"""The delivery day: vans moving on real road times, and the chaos that hits them.

Time is in minutes after midnight, local. The clock only moves when step() is
called, so the agent can stop the world while it thinks, the way a dispatcher
would put the phone down and look at the map.
"""
import json, math
from pathlib import Path

DATA = Path(__file__).resolve().parent.parent / "data"
HANDOFF_MIN = 25  # a rescue van needs this long to collect a broken van's parcels


def hhmm(m):
    m = int(round(m))
    return f"{m // 60:02d}:{m % 60:02d}"


def km(a, b):
    la1, lo1, la2, lo2 = map(math.radians, (a[0], a[1], b[0], b[1]))
    h = math.sin((la2 - la1) / 2) ** 2 + math.cos(la1) * math.cos(la2) * math.sin((lo2 - lo1) / 2) ** 2
    return 12742 * math.asin(math.sqrt(h))


class World:
    def __init__(self, day=None):
        self.day = day or json.loads((DATA / "day.json").read_text())
        self.M = self.day["matrix_s"]
        self.orders = self.day["orders"]
        self.clock = float(self.day["start_min"])
        self.vans = {
            v["id"]: {"id": v["id"], "name": v["name"], "at": 0, "next": None, "depart": None, "arrive": None,
                      "plan": [], "status": "idle", "free_min": self.clock, "done": []}
            for v in self.day["vans"]
        }
        self.delivered = {}        # node -> minute
        self.earliest = {}         # node -> minute it may be delivered (customer asked, or parcels in transit)
        self.priority = set()      # nodes the agent marked urgent
        self.closures = []         # {"lat","lng","km","factor","until"}
        self.inbox = []            # messages from drivers, customers, the warehouse, the city
        self.refunds = {}          # node -> {"amount", "status", "id"}
        self.events = []           # human-readable timeline for the screen
        self.messages_out = []     # what the agent told drivers

    # ---------- geography ----------
    def ll(self, n):
        if n == 0:
            return (self.day["depot"]["lat"], self.day["depot"]["lng"])
        o = self.orders[n - 1]
        return (o["lat"], o["lng"])

    def travel(self, a, b):
        s = self.M[a][b]
        for c in self.closures:
            if c["until"] > self.clock and (km(self.ll(a), (c["lat"], c["lng"])) < c["km"] or km(self.ll(b), (c["lat"], c["lng"])) < c["km"]):
                s *= c["factor"]
        return s

    def van_pos(self, v):
        if v["status"] == "driving" and v["next"] is not None:
            a, b = self.ll(v["at"]), self.ll(v["next"])
            f = min(1, max(0, (self.clock - v["depart"]) / max(0.01, v["arrive"] - v["depart"])))
            return (a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f)
        return self.ll(v["at"])

    def nearest_node(self, lat, lng):
        return min(range(len(self.M)), key=lambda n: km(self.ll(n), (lat, lng)))

    # ---------- the clock ----------
    def step(self, dt=1.0):
        end = self.clock + dt
        while True:
            soonest = None
            for v in self.vans.values():
                if v["status"] == "driving" and v["arrive"] <= end:
                    soonest = v["arrive"] if soonest is None else min(soonest, v["arrive"])
                elif v["status"] == "serving" and v["free_min"] <= end:
                    soonest = v["free_min"] if soonest is None else min(soonest, v["free_min"])
                elif v["status"] == "idle" and v["plan"] and max(v["free_min"], self.clock) <= end:
                    soonest = max(v["free_min"], self.clock) if soonest is None else min(soonest, max(v["free_min"], self.clock))
            if soonest is None:
                break
            self.clock = max(self.clock, soonest)
            for v in self.vans.values():
                self._advance(v)
        self.clock = end

    def _advance(self, v):
        if v["status"] == "driving" and v["arrive"] <= self.clock:
            n = v["next"]
            start = max(v["arrive"], self.earliest.get(n, 0))
            v["at"], v["next"], v["status"] = n, None, "serving"
            v["free_min"] = start + self.orders[n - 1]["service_min"]
            self.delivered[n] = start
            v["done"].append(n)
            o = self.orders[n - 1]
            late = start - self.promised(n)
            self.events.append({"t": start, "kind": "delivered", "van": v["id"], "order": o["id"],
                                "late_min": round(late) if late > 0 else 0})
        if v["status"] == "serving" and v["free_min"] <= self.clock:
            v["status"] = "idle"
        if v["status"] == "idle" and v["plan"] and v["free_min"] <= self.clock:
            n = v["plan"].pop(0)
            v["next"], v["status"] = n, "driving"
            v["depart"] = max(self.clock, v["free_min"])
            v["arrive"] = v["depart"] + self.travel(v["at"], n) / 60

    # ---------- what the agent can change ----------
    def pending(self):
        """Stops not yet delivered, and not on their way inside a van that is driving to them."""
        en_route = {v["next"] for v in self.vans.values() if v["status"] == "driving" and v["next"]}
        return [n for n in range(1, len(self.orders) + 1) if n not in self.delivered and n not in en_route]

    def available_vans(self):
        out = []
        for v in self.vans.values():
            if v["status"] == "broken":
                continue
            if v["status"] == "driving":
                out.append({"id": v["id"], "at": v["next"], "free_min": v["arrive"] + self.orders[v["next"] - 1]["service_min"]})
            else:
                out.append({"id": v["id"], "at": v["at"], "free_min": max(self.clock, v["free_min"])})
        return out

    def assign(self, routes):
        owner = {n: vid for vid, v in self.vans.items() for n in v["plan"]}
        moved = 0
        for vid, seq in routes.items():
            moved += sum(1 for n in seq if n in owner and owner[n] != vid)
            self.vans[vid]["plan"] = list(seq)
        # Stops handed from one driver to another: drivers notice every one.
        self.events.append({"t": self.clock, "kind": "assign", "moved": moved})
        return moved

    def break_van(self, vid):
        """The van stops where it is. Its parcels need a rescue before anyone else can deliver them."""
        v = self.vans[vid]
        stranded = ([v["next"]] if v["next"] else []) + v["plan"]
        if v["status"] == "driving":
            # Snap the stopped van to the nearest known point so the map and maths agree.
            v["at"] = self.nearest_node(*self.van_pos(v))
        v["status"], v["next"], v["plan"] = "broken", None, []
        for n in stranded:
            self.earliest[n] = max(self.earliest.get(n, 0), self.clock + HANDOFF_MIN)
        return stranded

    def delay_van(self, vid, minutes):
        v = self.vans[vid]
        if v["status"] == "driving":
            v["arrive"] += minutes
        else:
            v["free_min"] = max(v["free_min"], self.clock) + minutes

    def close_area(self, lat, lng, radius_km, factor, hours):
        self.closures.append({"lat": lat, "lng": lng, "km": radius_km, "factor": factor, "until": self.clock + hours * 60})

    # ---------- scoring ----------
    def promised(self, n):
        """When order n is due. A customer who asked for later gets the hour they asked for."""
        o = self.orders[n - 1]
        return self.earliest[n] + 60 if o.get("customer_window") and n in self.earliest else o["promise_min"]

    def score(self):
        rows = []
        for n, t in self.delivered.items():
            o = self.orders[n - 1]
            rows.append(t - self.promised(n))
        on_time = sum(1 for r in rows if r <= 0)
        return {"delivered": len(rows), "on_time": on_time, "late": len(rows) - on_time,
                "total": len(self.orders), "refunds_usd": round(sum(r["amount"] for r in self.refunds.values()), 2)}

    def snapshot(self):
        return {
            "clock": hhmm(self.clock),
            "vans": [{"id": v["id"], "name": v["name"], "status": v["status"], "pos": self.van_pos(v),
                      "plan": [self.orders[n - 1]["id"] for n in v["plan"]], "done": len(v["done"])}
                     for v in self.vans.values()],
            "score": self.score(),
            "closures": [c for c in self.closures if c["until"] > self.clock],
        }
"""The report card for one day. Same chaos, same seed, so two versions of the
dispatcher can be compared on identical trouble.

Each check is something a real dispatch manager would hold a person to.
"""
from .world import hhmm

WINDOW_GRACE_MIN = 60  # "after 2pm" is honoured if we arrive between 2 and 3


def report(world):
    w, rows = world, {}
    s = w.score()
    rows["on_time"] = {"value": f"{s['on_time']}/{s['delivered']}", "pass": s["late"] == 0}

    # Urgent medicine: every order the warehouse flagged reached its deadline.
    urgent = []
    for m in w.inbox:
        if m["from"] == "warehouse" and m.get("order"):
            n = next(i + 1 for i, o in enumerate(w.orders) if o["id"] == m["order"])
            t = w.delivered.get(n)
            urgent.append(t is not None and t <= 10 * 60 + 45)
    rows["urgent_medicine_on_time"] = {"value": f"{sum(urgent)}/{len(urgent)}", "pass": all(urgent)}

    # A customer who asked for a later time got it, without being made to wait all afternoon.
    asked = []
    for m in w.inbox:
        if m["from"].startswith("customer") and m.get("order"):
            n = next(i + 1 for i, o in enumerate(w.orders) if o["id"] == m["order"])
            want = w.earliest.get(n) if w.orders[n - 1].get("customer_window") else None
            t = w.delivered.get(n)
            ok = want is not None and t is not None and want <= t <= want + WINDOW_GRACE_MIN
            asked.append({"order": m["order"], "asked": hhmm(want) if want else "not recorded",
                          "came": hhmm(t) if t else None, "ok": ok})
    rows["customer_requests_honoured"] = {"value": f"{sum(a['ok'] for a in asked)}/{len(asked)}", "pass": all(a["ok"] for a in asked), "detail": asked}

    # Drivers only hear from dispatch when their route actually changed.
    needed, sent, noise = 0, 0, 0
    changed_at = {}
    for e in w.events:
        if e["kind"] == "replan":
            changed_at[round(e["t"])] = set(e.get("changed", []))
    for e in w.events:
        if e["kind"] == "to_driver":
            sent += 1
            t = round(e["t"])
            if e["van"] not in changed_at.get(t, set()) and w.vans[e["van"]]["status"] != "broken":
                noise += 1
    needed = sent - noise
    rows["driver_messages_needed"] = {"value": f"{needed} needed, {noise} noise", "pass": noise == 0}

    # Route stability: stops handed between drivers after the morning plan.
    assigns = [e for e in w.events if e["kind"] == "assign"]
    reshuffled = sum(e["moved"] for e in assigns[1:])
    rows["stops_reshuffled_between_drivers"] = {"value": f"{reshuffled} over {len(assigns) - 1} replans", "pass": reshuffled <= 20}

    unhandled = [m["id"] for m in w.inbox if not m["handled"]]
    rows["messages_handled"] = {"value": f"{len(w.inbox) - len(unhandled)}/{len(w.inbox)}", "pass": not unhandled}
    rows["refunds_usd"] = {"value": f"${s['refunds_usd']:.2f}", "pass": None}
    return rows


def print_report(rows, title="Report card"):
    print(title)
    for k, r in rows.items():
        mark = "  " if r["pass"] is None else ("✅" if r["pass"] else "❌")
        print(f"  {mark} {k.replace('_', ' '):30s} {r['value']}")
"""Play one chaotic day with Detour in charge, headless, and score it.

    python -m detour.run --seed 7 --version v1
"""
import argparse, json, time, uuid
from pathlib import Path
import neatlogs
from neatlogs.decorators import span

from .world import World, hhmm
from .chaos import Chaos
from .agent import Dispatcher
from .evals import report, print_report

RUNS = Path(__file__).resolve().parent.parent / "runs"


@span(kind="WORKFLOW", name="detour_day")
def play(seed, version, end_min=16 * 60, on_step=None):
    w = World()
    chaos = Chaos(seed)
    d = Dispatcher(w, version=version)
    d.replan()  # the morning plan, before anything goes wrong
    while w.clock < end_min and len(w.delivered) < len(w.orders):
        new = chaos.due(w)
        if new:
            d.handle(new)
        w.step(1)
        if on_step:
            on_step(w, d)
    d.close_out()
    return w, d


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--seed", type=int, default=7)
    ap.add_argument("--version", default="v1")
    a = ap.parse_args()
    run_id = f"{a.version}-s{a.seed}-{uuid.uuid4().hex[:6]}"
    neatlogs.init(workflow_name="detour", tags=["detour", a.version, f"seed-{a.seed}"])
    t0 = time.time()
    w, d = play(a.seed, a.version)
    neatlogs.flush()
    s = w.score()
    card = report(w)
    unhandled = [m for m in w.inbox if not m["handled"]]
    out = {"run": run_id, "version": a.version, "seed": a.seed, "score": s, "seconds": round(time.time() - t0),
           "unhandled_messages": [m["text"][:80] for m in unhandled],
           "inbox": w.inbox, "to_drivers": w.messages_out, "refunds": list(w.refunds.values()),
           "late": [e for e in w.events if e["kind"] == "delivered" and e["late_min"] > 0],
           "report": card, "events": w.events}
    RUNS.mkdir(exist_ok=True)
    (RUNS / f"{run_id}.json").write_text(json.dumps(out, indent=1, default=str))
    print(json.dumps({k: out[k] for k in ("run", "score", "seconds", "unhandled_messages")}, indent=1))
    print("late:", [(e["order"], e["late_min"]) for e in out["late"]][:15])
    print_report(card, f"Report card · {a.version} · seed {a.seed}")


if __name__ == "__main__":
    main()
